import { readFileSync } from "node:fs";

export function loadPriceList(path: string): Map<string, number> {
  const rows = readFileSync(path, "utf8").trim().split("\n").slice(1);
  return new Map(rows.map((r) => { const [code, cents] = r.split(","); return [code, Number(cents)]; }));
}

