export async function nextChainNumber(year: number): Promise<number> {
  const { rows } = await pool.query(
    "INSERT INTO chain_counter (year, last) VALUES ($1, 1) ON CONFLICT (year) DO UPDATE SET last = chain_counter.last + 1 RETURNING last",
    [year],
  );
  return rows[0].last;
}

