files.src/numbering/reserve.ts:
import type { PoolClient } from "pg";

// Number and invoice row are written in one transaction; nothing is cached across restarts.
export async function issueWithNumber(client: PoolClient, year: number, insert: (n: number) => Promise<void>) {
  await client.query("BEGIN");
  const { rows } = await client.query("UPDATE chain_counter SET last = last + 1 WHERE year = $1 RETURNING last", [year]);
  await insert(rows[0].last);
  await client.query("COMMIT");
}

