CREATE MATERIALIZED VIEW invoice_lines_mv AS
SELECT l.id AS line_id, i.clinic_id, i.issued_on, l.category, p.species, i.vet_id, l.total_cents
FROM invoices i
JOIN invoice_lines l ON l.invoice_id = i.id
JOIN patients p ON p.id = i.patient_id;
CREATE UNIQUE INDEX ON invoice_lines_mv (line_id);

